# Tests of bcclass.jl.  Run from bc/:  julia --project=. proj/bcclass_tests.jl
include("bcclass.jl")
using .BCClass, Oscar
const B = BCClass.B
npass = 0; nfail = 0
function check(name, cond)
    global npass, nfail
    cond ? (npass += 1) : (nfail += 1)
    println(cond ? "  [PASS] " : "  [FAIL] ", name)
end

# ---- S3: BC_2(S3) = Z/2, generated by the point class (C3, C3, (1,1)) ----
S3 = GAP.Globals.SymmetricGroup(3)
prepare!(S3)
c3 = GAP.evalstr("(1,2,3)")
t = [(1, [c3], [c3], [[1], [1]])]
check("S3: (C3,C3,(1,1)) nonzero in BC_2(S3)", !class_is_zero(S3, 2, t))
check("S3: it has order 2", class_order(S3, 2, t) == 2)
check("S3: 2*(C3,C3,(1,1)) = 0", class_is_zero(S3, 2, [(2, [c3], [c3], [[1], [1]])]))
# (1,2) is conjugate to (2,1): the weights (1,1) and (2,2) give the same class (C), inversion is in N(H)
check("S3: (C3,C3,(2,2)) = (C3,C3,(1,1))", class_is_zero(S3, 2, [(1, [c3], [c3], [[1], [1]]), (-1, [c3], [c3], [[2], [2]])]))
# (V): weights (1,2) vanish
check("S3: (C3,C3,(1,2)) = 0 by (V)", class_is_zero(S3, 2, [(1, [c3], [c3], [[1], [2]])]))
# B2 for beta=(1,1): (b,b) = (0,b): the divisor symbol (C3,C3,(1)) equals the point symbol (C3,C3,(1,1))
check("S3: (C3,C3,(1)) = (C3,C3,(1,1)) (blowup relation b1=b2)",
      class_is_zero(S3, 2, [(1, [c3], [c3], [[1]]), (-1, [c3], [c3], [[1], [1]])]))

# ---- Example 6.3 of the paper (D7 on P^3): the three point symbols are nonzero and equal in BC_3(D7) = Z/2 ----
D7 = GAP.evalstr("DihedralGroup(IsPermGroup,14)")
r7 = GAP.evalstr("First(AsList(DihedralGroup(IsPermGroup,14)), x->Order(x)=7)")
prepare!(D7)
check("D7: BC_3(D7) = Z/2", string(B.bc(D7, 3).total) == "Z/2")
imgs = [first(class_coords(D7, 3, [(1, [r7], [r7], [[x] for x in w])])) for w in ([1,1,2], [2,4,6], [2,3,6])]
check("D7: the three symbols of Example 6.3 are nonzero", all(!all(x -> x == 0, v) for im in imgs for v in values(im)))
check("D7: they are equal", imgs[1] == imgs[2] == imgs[3])
check("D7: their sum (the class) is nonzero in BC_3(D7)",
      !class_is_zero(D7, 3, [(1, [r7], [r7], [[x] for x in w]) for w in ([1,1,2], [2,4,6], [2,3,6])]))

println("passed $npass, failed $nfail")
exit(nfail == 0 ? 0 : 1)
